import{_ as r,p as s,q as n,s as e,R as a,t as p,Y as o,n as c}from"./framework-e1bed10d.js";const d="/my-blog/assets/042_01-2731db66.png",i="/my-blog/assets/042_02-76fbc612.png",h="/my-blog/assets/042_03-61c341be.png",_={},l=e("h1",{id:"日终批量-核心的脉搏",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#日终批量-核心的脉搏","aria-hidden":"true"},"#"),a(" 日终批量：核心的脉搏")],-1),f={href:"https://mp.weixin.qq.com/s?__biz=MzIzNzQ5NjU5NQ==&mid=2247484992&idx=1&sn=d8c91eaf5cd80bd4f21a03f586b2c4ef&chksm=e8c6f63cdfb17f2a2802094026f6aa4d1fb68523b7b4e5cb325453aababa542ed63402e9e347",target:"_blank",rel:"noopener noreferrer"},b=o('<hr><p>六、日终批量：核心的脉搏</p><p><img src="'+d+'" alt="图片"></p><p><strong>图5-13 日终批量：核心的脉搏——切日、任务链与关键机制</strong></p><h3 id="一-日切-系统工作日" tabindex="-1"><a class="header-anchor" href="#一-日切-系统工作日" aria-hidden="true">#</a> （一）日切：系统工作日</h3><p>核心系统不直接用自然日，而是有自己的一套“系统工作日”，由日切来控制：日切之后，上一个交易日结束，系统进入下一个交易日。</p><p>为什么不用自然日？三个原因：</p><p>第一，自然日受系统时钟影响，时间错了交易就全错；</p><p>第二，系统工作日便于控制日终时间，月结、年结时可以提前切换到下月1号；第三，测试需要，按自然日做日终，测试只能不停改系统时间。</p><p>日切具体怎么落地？不同机构之间，日切时间也不一样，按各自的业务需要来设定：有的定在22:30，有的定在零点刚过，有的定在凌晨。工程实现上，各系统时间先通过时钟同步器对齐，日切时由核心统一下达指令，等各系统都确认响应成功后，才真正开始日切；日切操作支持自动触发，也支持手工发起。</p><p><img src="'+i+'" alt="图片"></p><p><strong>图5-14 为什么不用自然日：三个原因</strong></p><h3 id="二-日终任务链" tabindex="-1"><a class="header-anchor" href="#二-日终任务链" aria-hidden="true">#</a> （二）日终任务链</h3><p>日终批量是一串按顺序执行的任务。我列一份我在互金平台做核心时真实的日终任务链给你看，顺序就是执行顺序，不能乱：</p><h4 id="清单5-1-日终批量任务链-按执行顺序" tabindex="-1"><a class="header-anchor" href="#清单5-1-日终批量任务链-按执行顺序" aria-hidden="true">#</a> 清单5-1 日终批量任务链（按执行顺序）</h4><p>①日切→ ②节假日处理→ ③贷款状态变更→ ④减免息逾期超限计划恢复→ ⑤计提→ ⑥计提入账→ ⑦特殊期供到期处理→ ⑧借据金额维护→ ⑨形态转列→ ⑩利息转列→ ⑪总分核对→ ⑫每日余额统计→ ⑬昨日余额维护→ ⑭分段还款利率维护→ ⑮滞纳金计算→ ⑯交易日期同步。</p><p>这条链的依赖很清楚：先切日（①），再处理节假日顺延（②），然后算状态（③）、算利息（⑤⑥），再做转列（⑨⑩），最后对账（⑪）。每一步失败都要有断点续跑能力，批量跑了30分钟在任务⑨挂了，重跑要从⑨继续，而不是从头来。</p><p><img src="'+h+'" alt="图片"></p><p><strong>图5-15 日终批量任务链与依赖</strong></p><h3 id="三-节假日顺延" tabindex="-1"><a class="header-anchor" href="#三-节假日顺延" aria-hidden="true">#</a> （三）节假日顺延</h3><p>还款止日落在节假日，要顺延到第一个工作日，顺延期间不计逾期。为什么？客户节假日线下打款，工作人员休息、未能及时入账，这是机构的责任，不能算客户逾期。</p><p>注意：节假日顺延不是生成计划时就定死的，而是节假日当天日终才决定是否顺延、一天天顺延，因为当年不可能提前知道下一年的全部节假日，而且节假日可能临时调整（2020年疫情就调过）。所以实现上是“日终动态判定”，不是“计划预生成”。</p><p>总分核对是日终批量的最后一道关。机构账（汇总）和客户账（明细）必须核对一致：所有客户账的本金余额之和，应该等于机构账的正常本金余额；所有客户账的应收利息之和，应该等于机构账的应收利息余额。核对不一致就要挂账查找，不能带着差异进入下一个交易日。</p><p>形态转列是日终任务链的第⑨步，根据逾期天数把本金和利息做转列：正常本金转逾期本金，逾期90天以上转非应计并冲回应收利息（规则见本章五（三），科目转移与分录在第六章展开）。判断逻辑不复杂，但要卡准时点：差一天，报表数据就错。</p><p>计提是日终批量的核心任务。依照权责发生制，资金占用一天就要记一天利息，即使没收到钱也要记应收。两种算法（累加法/差额计提）本章四（二）已讲过，日终任务里它排在⑤⑥两步：先按期供算出每日计提，再按产品汇总入账，挂应收利息；对应的入账分录，第六章核算日终会讲。</p><p>这条链跑完，核心当天的账务才真正闭环：任何一步出错，第二天就带着错误的账跑，所以断点续跑和总分核对缺一不可。</p>',26);function m(g,u){const t=c("ExternalLinkIcon");return s(),n("div",null,[l,e("blockquote",null,[e("p",null,[a("公众号：侃西东　·　发布日期：2026-10-28　·　"),e("a",f,[a("微信原文"),p(t)])])]),b])}const k=r(_,[["render",m],["__file","042.html.vue"]]);export{k as default};
